.subtitle{font-size:14px;bottom:145px}.notification{top:68px;font-size:8px}.letter{padding:42px 32px 32px}}
.mobile-controls{display:none}
.touch-device #scene{touch-action:none}
@media (pointer:coarse){
 .mobile-controls{display:block;position:absolute;inset:0;pointer-events:none;z-index:4}
 .move-stick{position:absolute;left:max(22px,env(safe-area-inset-left));bottom:max(28px,env(safe-area-inset-bottom));width:132px;height:132px;border-radius:50%;border:1px solid rgba(226,214,188,.32);background:rgba(15,17,15,.28);pointer-events:auto;touch-action:none;display:grid;place-items:center;box-shadow:inset 0 0 24px rgba(0,0,0,.2)}
 .move-stick:before{content:'';position:absolute;width:62%;height:62%;border:1px solid rgba(226,214,188,.16);border-radius:50%}
 .move-stick-knob{position:absolute;width:48px;height:48px;border-radius:50%;background:rgba(204,190,160,.55);border:1px solid rgba(239,227,201,.66);box-shadow:0 3px 14px #0006;will-change:transform}
 .touch-action{position:absolute;pointer-events:auto;touch-action:manipulation;border:1px solid rgba(226,214,188,.4);border-radius:50%;background:rgba(18,20,17,.62);color:#e8e2d4;font:9px 'DM Mono',monospace;letter-spacing:.5px;display:grid;place-items:center;box-shadow:0 3px 18px #0005;-webkit-tap-highlight-color:transparent}
 .touch-interact{right:max(28px,env(safe-area-inset-right));bottom:max(44px,env(safe-area-inset-bottom));width:68px;height:68px;background:rgba(116,91,58,.75)}
